import java.io.*;
import java.util.*;

public class Main {
    static int[] head, to, nx, dist, par, order;

    static int bfs(int src, int block) {
        Arrays.fill(dist, -1);
        int qt = 0, qh = 0;
        dist[src] = 0;
        order[qt++] = src;
        int far = src;
        while (qh < qt) {
            int x = order[qh++];
            for (int e = head[x]; e != -1; e = nx[e]) {
                int y = to[e];
                if (dist[y] == -1 && !(x == src && y == block)) {
                    dist[y] = dist[x] + 1;
                    par[y] = x;
                    if (dist[y] > dist[far]) far = y;
                    order[qt++] = y;
                }
            }
        }
        return far;
    }

    static long[] distCounts(int src, int block, int n, int D) {
        bfs(src, block);
        long[] c = new long[D + 1];
        for (int x = 1; x <= n; x++) if (dist[x] >= 0) c[dist[x]]++;
        return c;
    }

    static int nextInt(DataInputStream in) throws IOException {
        int ret = 0;
        int b = in.read();
        while (b < '0' || b > '9') b = in.read();
        while (b >= '0' && b <= '9') {
            ret = ret * 10 + (b - '0');
            b = in.read();
        }
        return ret;
    }

    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));
        int n = nextInt(in);
        int m = n - 1;
        head = new int[n + 1];
        Arrays.fill(head, -1);
        to = new int[2 * m];
        nx = new int[2 * m];
        int cnt = 0;
        for (int i = 0; i < m; i++) {
            int x = nextInt(in), y = nextInt(in);
            to[cnt] = y; nx[cnt] = head[x]; head[x] = cnt++;
            to[cnt] = x; nx[cnt] = head[y]; head[y] = cnt++;
        }
        dist = new int[n + 1];
        par = new int[n + 1];
        order = new int[n];

        int u = bfs(1, -1);
        int v = bfs(u, -1);
        int D = dist[v];
        long count;

        if ((D & 1) == 0) {
            int k = D >> 1;
            int c = v;
            for (int i = 0; i < k; i++) c = par[c];
            bfs(c, -1);

            long[] f = new long[D + 1];
            for (int x = 1; x <= n; x++) if (x != c) f[dist[x]]++;

            int[] branchOf = new int[n + 1];
            for (int i = 0; i < n; i++) {
                int x = order[i];
                if (x == c) continue;
                branchOf[x] = (par[x] == c) ? x : branchOf[par[x]];
            }

            int nb = 0;
            int[] idxOf = new int[n + 1];
            Arrays.fill(idxOf, -1);
            for (int e = head[c]; e != -1; e = nx[e]) idxOf[to[e]] = nb++;

            int[] cntB = new int[nb];
            for (int x = 1; x <= n; x++) if (x != c) cntB[idxOf[branchOf[x]]]++;
            int[] start = new int[nb + 1];
            for (int i = 0; i < nb; i++) start[i + 1] = start[i] + cntB[i];
            int[] ptr = new int[nb];
            System.arraycopy(start, 0, ptr, 0, nb);
            int[] bucket = new int[n];
            for (int x = 1; x <= n; x++) if (x != c) bucket[ptr[idxOf[branchOf[x]]]++] = x;

            long sameBranch = 0;
            int[] loc = new int[D + 1];
            int[] touched = new int[D + 1];
            for (int b = 0; b < nb; b++) {
                int t = 0;
                for (int p = start[b]; p < start[b + 1]; p++) {
                    int x = bucket[p];
                    int d = dist[x];
                    if (loc[d] == 0) touched[t++] = d;
                    loc[d]++;
                }
                long inner = 0;
                for (int d = 0; d <= D; d++) inner += (long) loc[d] * loc[D - d];
                sameBranch += inner;
                for (int i = 0; i < t; i++) loc[touched[i]] = 0;
            }

            long total = 0;
            for (int d = 0; d <= D; d++) total += f[d] * f[D - d];
            count = (total - sameBranch) / 2;
        } else {
            int k = D >> 1;
            int cur = v;
            for (int i = 0; i < k; i++) cur = par[cur];
            int b = cur;
            int a = par[cur];
            long[] va = distCounts(a, b, n, D);
            long[] vb = distCounts(b, a, n, D);
            count = 0;
            for (int d = 0; d <= D - 1; d++) count += va[d] * vb[D - 1 - d];
        }

        BufferedWriter out = new BufferedWriter(new OutputStreamWriter(System.out));
        out.write(String.valueOf(D + 1));
        out.write('\n');
        out.write(String.valueOf(count));
        out.write('\n');
        out.flush();
    }
}
